package com.quickbite.deployment.config;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.JwtException; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.List;
@Configuration @EnableWebSecurity public class SecurityConfig {
@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
@Bean SecurityFilterChain filterChain(HttpSecurity http,JwtFilter jwtFilter)throws Exception{http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/auth/register","/auth/login","/actuator/**","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers(HttpMethod.GET,"/restaurants/**","/images/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwtFilter,UsernamePasswordAuthenticationFilter.class);return http.build();}
@Bean JwtFilter jwtFilter(@Value("${security.jwt.secret}") String secret){return new JwtFilter(secret);}
static final class JwtFilter extends OncePerRequestFilter{private final SecretKey signingKey; JwtFilter(String secret){signingKey=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}
@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{Claims c=Jwts.parserBuilder().setSigningKey(signingKey).build().parseClaimsJws(h.substring(7)).getBody();Long id=((Number)c.get("userId")).longValue();String role=String.valueOf(c.get("role"));var auth=new UsernamePasswordAuthenticationToken(id,null,List.of(new SimpleGrantedAuthority("ROLE_"+role)));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(auth);}catch(JwtException|IllegalArgumentException ignored){org.springframework.security.core.context.SecurityContextHolder.clearContext();}}chain.doFilter(req,res);}}}